{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "EM574, a macrolide, has an estimated human oral bioavailability of about 2%, directly supporting low F for a macrolide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "A complex glycoside with high transfer score showed low oral bioavailability relative to assay LLOQ, supporting low absorption for large glycosylated macrocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Cefditoren absolute bioavailability is about 14% in fasting humans, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Glycyrrhizin oral bioavailability is about 0.25%, extremely low, supporting low F for glycoside-like drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Withaferin A showed poor oral bioavailability in humans, supporting low F for a lipophilic macrocyclic lactone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808 absolute bioavailability was 10.1%, below threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Oseltamivir has high oral bioavailability (79±12%), but it is a small ester prodrug, not a macrolide; this is contradictory but weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Etoposide absolute bioavailability was 57±35%, above threshold, but it is a podophyllotoxin glycoside with lower transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, especially the macrolide EM574 with ~2% F and multiple glycoside/macrolide-like low-F analogues, supports low oral bioavailability (<20%). High-F comparators are structurally distant and less transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "Exact structural class of the query is not fully resolved from the SMILES.",
    "High-F comparators (oseltamivir, etoposide) are structurally distant from the query.",
    "Potential species differences and formulation effects are not captured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

